import{_ as e,a as i,c as a,ac as t}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"Redis Stream（消息流） · 3. 底层编码与内存至8. Go 客户端与最佳实践","description":"事件记录、消费组与比赛结果入库，包括基本操作、适用场景和使用边界。","frontmatter":{"title":"Redis Stream（消息流） · 3. 底层编码与内存至8. Go 客户端与最佳实践","description":"事件记录、消费组与比赛结果入库，包括基本操作、适用场景和使用边界。","splitFrom":"middleware/redis/plus/subjects/stream.md","showdocs":{"topics":[{"id":"redis","title":"Redis","link":"/topics/redis/"}],"kind":"数据与原子性","scope":"general","audience":"general","group":"数据库与存储","seriesTitle":"Redis Stream（消息流）","summary":"事件记录、消费组与比赛结果入库，包括基本操作、适用场景和使用边界。","status":"active","related":[{"title":"Redis 操作与命令","link":"/middleware/redis/plus/ecosystem/redis-general-general","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 数据类型命令速查","link":"/middleware/redis/plus/subjects/redis-data-cmd","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 完整实践：Lua 原子限额与可重试 CLI","link":"/middleware/redis/plus/practice/quota","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 游戏与通用后端场景","link":"/middleware/redis/pro/practice/game-scenarios","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 持久化：RDB、AOF 与独立恢复","link":"/middleware/redis/persistence-and-recovery","kind":"数据与原子性","scope":"general","audience":"general"}],"prev":{"text":"Redis Stream（消息流） · 2. 命令速查与示例","link":"/middleware/redis/plus/subjects/stream-part-02"},"next":{"text":"Redis Bitmap（位图）","link":"/middleware/redis/plus/subjects/bitmap"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Redis Stream（消息流） · 2. 命令速查与示例","link":"/middleware/redis/plus/subjects/stream-part-02"},"next":{"text":"Redis Bitmap（位图）","link":"/middleware/redis/plus/subjects/bitmap"}},"headers":[],"relativePath":"middleware/redis/plus/subjects/stream-part-03.md","filePath":"middleware/redis/plus/subjects/stream-part-03.md"}'),r={name:"middleware/redis/plus/subjects/stream-part-03.md"};function n(l,s,p,d,h,k){return i(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="redis-stream-消息流-·-3-底层编码与内存至8-go-客户端与最佳实践" tabindex="-1">Redis Stream（消息流） · 3. 底层编码与内存至8. Go 客户端与最佳实践 <a class="header-anchor" href="#redis-stream-消息流-·-3-底层编码与内存至8-go-客户端与最佳实践" aria-label="Permalink to &quot;Redis Stream（消息流） · 3. 底层编码与内存至8. Go 客户端与最佳实践&quot;">​</a></h1><p><a href="/middleware/redis/plus/subjects/stream">返回分篇目录</a></p><p>本文按 Redis 8.2.10 核对编码与配置默认值；命令的引入版本另行标注。生产配置可能不同，可通过 CONFIG GET 查询。示例面向独立实验服务，运行结果和内存数字未在本次实测。</p><h2 id="encoding" tabindex="-1">3. 底层编码与内存 <a class="header-anchor" href="#encoding" aria-label="Permalink to &quot;3. 底层编码与内存 {#encoding}&quot;">​</a></h2><p>Stream 使用 <code>stream</code> 编码，内部为 radix tree 组织的 listpack 节点；消费组、消费者与待处理条目还占用额外结构。不存在按普通 Hash 阈值切成 hashtable 的规则。</p><p>8.2.10 默认 <code>stream-node-max-bytes 4096</code>、<code>stream-node-max-entries 100</code>，用于控制内部节点，不限制整条流长度。实际保留必须配置 XADD MAXLEN/MINID 或 XTRIM 等策略。</p><h3 id="编码与内存怎么测" tabindex="-1">编码与内存怎么测 <a class="header-anchor" href="#编码与内存怎么测" aria-label="Permalink to &quot;编码与内存怎么测 {#编码与内存怎么测}&quot;">​</a></h3><p>在独立实验实例准备教学键，再读实际状态；下列是测量方法，本次未运行或填写测量数字：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>XADD learn:types:events * action login user 42</span></span>
<span class="line"><span>OBJECT ENCODING learn:types:events</span></span>
<span class="line"><span>MEMORY USAGE learn:types:events</span></span></code></pre></div><p>固定键名、元素字节长度、Redis 版本和分配器，分别记录 1、10、100 个元素或不同值长度时的内存，再跨越编码阈值观察。单元素的增量开销可用相邻两次内存差估计，编码转换时不能套用线性平均；String/Bitmap 的横轴应使用字节数或最高位偏移。比较“一键多元素”和“多个独立键”时，把键名、对象、字典项和 TTL 管理开销一起计入。</p><p>MEMORY USAGE 默认对嵌套值采样，<code>SAMPLES 0</code> 会遍历所有嵌套值，仅在小型隔离实验中使用。其结果不等同于进程 RSS；大量键还会增加全局字典、分配器碎片和复制缓冲等成本，需结合 INFO memory。没有适用于所有版本的固定“每 key 几字节”。</p><p>依据：<a href="https://github.com/redis/redis/blob/8.2.10/redis.conf" target="_blank" rel="noopener noreferrer">8.2.10 配置</a>、<a href="https://github.com/redis/redis/blob/8.2.10/src/t_stream.c" target="_blank" rel="noopener noreferrer">对应类型实现</a>、<a href="https://redis.io/docs/latest/commands/memory-usage/" target="_blank" rel="noopener noreferrer">MEMORY USAGE</a>。</p><h2 id="performance" tabindex="-1">4. 性能与阻塞风险 <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;4. 性能与阻塞风险 {#performance}&quot;">​</a></h2><p>限制 XRANGE/XREADGROUP 的 COUNT，避免一次取回无界历史。没有 XSCAN；可用 ID 游标分页，并处理裁剪造成的空洞。长时间 BLOCK 是消费者等待，多个等待者被唤醒会增加生产者工作。大量 PEL 和消费者也会增加内存及维护成本。</p><p>常规命令执行主要占用主执行路径，耗时计算会拖慢同实例其他请求；网络 I/O、后台持久化和释放内存有其他线程/进程参与。命令复杂度不包含所有网络、分配、编码转换与客户端成本。</p><h2 id="atomicity" tabindex="-1">5. 原子性与并发 <a class="header-anchor" href="#atomicity" aria-label="Permalink to &quot;5. 原子性与并发 {#atomicity}&quot;">​</a></h2><p>XADD、XACK 分别原子，但“读取消息 → 写数据库 → XACK”是跨系统流程。数据库提交后确认，提交成功但确认前崩溃可能导致重投，必须用事件 ID 或比赛 ID 防重。脚本不能把外部数据库事务纳入 Redis 原子执行。</p><p>MULTI/EXEC 保证排队命令连续执行，但执行时单条报错不会回滚其他已成功命令；WATCH 是乐观冲突检测，需要有界重试。Lua 也不会自动回滚运行错误前的写入，应先校验参数与类型，再修改状态。</p><h2 id="lifecycle" tabindex="-1">6. 过期、持久化与生命周期 <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;6. 过期、持久化与生命周期 {#lifecycle}&quot;">​</a></h2><p>TTL 作用于整条流，不能按单条消息直接 EXPIRE。MAXLEN、MINID 或 XTRIM 管理历史；裁剪需配合待确认条目及业务保留期。XACK 只处理消费组确认，不能当成删除正文。持久化和副本策略决定故障后还能恢复哪些消息。</p><p>大键会增加 RDB/AOF 重写、复制全量同步和恢复时的处理量，fork 写时复制还可能增加峰值内存。单次同步删除聚合对象可能阻塞；<code>UNLINK</code> 先摘除键，把主要回收工作移到后台，但总回收工作和内存压力仍存在，不能替代限长和拆分。</p><p>完成教学实验后，只清理自己创建的键，例如 <code>UNLINK learn:types:events</code>。</p><h2 id="cluster" tabindex="-1">7. 集群与扩展 <a class="header-anchor" href="#cluster" aria-label="Permalink to &quot;7. 集群与扩展 {#cluster}&quot;">​</a></h2><p>一条流在一个槽，消费组也跟随该流；按区域拆流后需要业务明确跨流顺序和汇总。多流读或脚本需核对同槽要求。消费组读取修改主节点的消费状态，不能简单当成副本只读请求；副本的观测数据还可能落后。</p><p>一个键只在一个分片中，hash tag 控制相关键进入同一槽，不会把一个大键切开。副本读取通常是最终一致观察；操作后立即读到本次写入的需求应选主节点或明确的协调策略。</p><h2 id="client" tabindex="-1">8. Go 客户端与最佳实践 <a class="header-anchor" href="#client" aria-label="Permalink to &quot;8. Go 客户端与最佳实践 {#client}&quot;">​</a></h2><p>下面函数使用 <code>github.com/redis/go-redis/v9</code>，调用方提供 <code>context.Context</code> 和已配置认证、超时的 <code>*redis.Client</code>。</p><div class="language-go vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> StreamExample</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ctx</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> context</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Context</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">rdb</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Client</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">consumer</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) ([]</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">XStream</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">error</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> rdb.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">XReadGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">XReadGroupArgs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        Group: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;writers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, Consumer: consumer,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        Streams: []</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;learn:go:results&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}, Count: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, Block: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Result</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>先建立 writers 消费组，使用稳定且唯一的消费者名。此例 Block:-1 表示不发送 BLOCK；空结果需处理 redis.Nil。结果为 []redis.XStream，条目 Values 是 map，解析字段需检查类型。持久化成功后再逐条或批量 XAck，失败保留待处理；Pipeline 不能省略成功条件。</p><p>普通 Pipeline 只是批量发送，不能充当事务；批次过大也会增加响应缓冲与延迟。对超时后的写入重试，需要根据幂等性判断，不能把“没收到响应”当成“没执行”。</p><h3 id="继续阅读" tabindex="-1">继续阅读 <a class="header-anchor" href="#继续阅读" aria-label="Permalink to &quot;继续阅读 {#继续阅读}&quot;">​</a></h3><p><a href="/middleware/redis/base/basic/data-types">数据类型总览</a> · <a href="/middleware/redis/pro/practice/game-scenarios">游戏与通用后端实践</a> · <a href="/middleware/redis/base/basic/transactions">原子性基础</a>。</p><p>参考：<a href="https://github.com/redis/redis/tree/8.2.10/src/commands" target="_blank" rel="noopener noreferrer">Redis 8.2.10 命令定义</a>、<a href="https://github.com/redis/go-redis" target="_blank" rel="noopener noreferrer">go-redis</a>、<a href="https://redis.io/docs/latest/operate/oss_and_stack/reference/cluster-spec/" target="_blank" rel="noopener noreferrer">集群规格</a>。</p>`,33)])])}const E=e(r,[["render",n]]);export{c as __pageData,E as default};
